/* ADMIN DUPLICATE CONTROLS FIX V1
 * Keep the single global toolbar controls from admin.html.
 * Remove the duplicate page-local Aggiorna / Nuovo torneo controls
 * generated by admin-layout-v2.js.
 *
 * PARTICIPANTS FIX:
 * Refresh registrations before opening the Partecipanti page so the
 * page always renders the currently approved players of the selected tournament.
 */
(()=>{
'use strict';
function removeDuplicates(){
  document.getElementById('newTournament')?.remove();
  document.getElementById('refreshTournaments')?.remove();
}
function bindParticipantsRefresh(){
  const original=window.openAdminPage;
  if(typeof original!=='function'||original.__participantsFixBound)return;
  const wrapped=async function(page){
    if(page==='partecipanti'&&typeof window.caricaRichiesteIscrizione==='function'){
      await window.caricaRichiesteIscrizione();
    }
    return original.apply(this,arguments);
  };
  wrapped.__participantsFixBound=true;
  window.openAdminPage=wrapped;
}
function init(){
  const root=document.getElementById('appContent');
  if(!root)return;
  removeDuplicates();
  bindParticipantsRefresh();
  new MutationObserver(removeDuplicates).observe(root,{childList:true,subtree:true});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});
else init();
})();
